public class Issue96_second_highest_unique_score { public static void main(String[] args) { int[] v=new int[]{10, -10, 11, 8, 13}; int first=v[0], second=v[1]; for(int n:v) { if(n>first) { second=first; first=n; } else if(n>second && n!=first) second=n; } System.out.println("Second largest: "+first); } }
